const menu=document.querySelector('.menu');const nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Fechar menu':'Abrir menu');nav.classList.toggle('open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Abrir menu')}));document.querySelectorAll('[data-service]').forEach(a=>a.addEventListener('click',()=>{document.querySelector('#service').value=a.dataset.service}));document.querySelector('#quote-form').addEventListener('submit',e=>{e.preventDefault();const name=document.querySelector('#name').value.trim();const project=document.querySelector('#project').value.trim();if(!name||!project){return}const service=document.querySelector('#service').value;const message=`Olá, Haptos 3D! Meu nome é ${name}.\n\nTenho interesse em: ${service}.\n\nMeu projeto: ${project}`;window.open('https://wa.me/5511932845696?text='+encodeURIComponent(message),'_blank','noopener')});document.querySelector('#year').textContent=new Date().getFullYear();
